import std.io

pub type AppError = Failed(String)

interface Shape {
    fn area(self) -> Int64
}

record Square { s: Int64 }

impl Shape for Square {
    fn area(self) -> Int64 { 4 }
}

pub fn main() effect io -> Result<(), AppError> {
    let d = Dyn<Shape>(Square { s: 1 })
    let n = d.area() + 1
    io.println("${n}")
    return Ok(())
}
